#include <iostream>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <cassert>
using namespace std;

using ll = long long;
using ld = long double;

const ll MOD = 1000000007;

struct Mod {
    ll num;
    Mod(ll n = 0) : num((n % MOD + MOD) % MOD) {}
    operator ll() const { return num; }
};

Mod operator+(const Mod& a, const Mod& b) { return Mod((a.num + b.num) % MOD); }
Mod operator-(const Mod& a, const Mod& b) { return Mod((a.num - b.num + MOD) % MOD); }
Mod operator*(const Mod& a, const Mod& b) { return Mod((a.num * b.num) % MOD); }
Mod& operator+=(Mod& a, const Mod& b) { return a = a + b; }
Mod& operator-=(Mod& a, const Mod& b) { return a = a - b; }
Mod& operator*=(Mod& a, const Mod& b) { return a = a * b; }

Mod modPow(Mod base, int exp) {
    Mod res(1);
    while (exp) {
        if (exp & 1) res *= base;
        base *= base;
        exp >>= 1;
    }
    return res;
}

Mod modInv(const Mod& a) { return modPow(a, MOD - 2); }
Mod operator/(const Mod& a, const Mod& b) { return a * modInv(b); }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<vector<Mod>> pers(6, vector<Mod>(6));

    int N;
    cin >> N;
    int s = 3 - (N + 1) / 2;

    for (int i = 0; i < s; ++i) {
        pers[i][i] = Mod(1);
    }

    for (int i = s; i < s + N; ++i) {
        for (int j = s; j < s + N; ++j) {
            int p;
            cin >> p;
            pers[i][j] = Mod(p) / Mod(100);
        }
    }

    for (int i = s + N; i < 6; ++i) {
        pers[i][i] = Mod(1);
    }

    // Generate all permutations of {0,0,0,1,1,1}
    vector<int> v = {0, 0, 0, 1, 1, 1};
    map<int, int> permMap;
    int id = 0;
    do {
        int mask = 0;
        for (int k = 0; k < 6; ++k) {
            if (v[k]) mask |= (1 << k);
        }
        permMap[mask] = id++;
    } while (next_permutation(v.begin(), v.end()));

    // Lambda for solving
    auto solve = [&](int offset) -> vector<Mod> {
        vector<Mod> result(1 << 20, Mod(0));
        for (int mask = 0; mask < (1 << 18); ++mask) {
            vector<vector<int>> haves(3, vector<int>(6, 0));
            Mod prob(1);

            for (int i = 0; i < 3; ++i) {
                for (int j = 0; j < 6; ++j) {
                    int idx = i * 6 + j;
                    if (mask & (1 << idx)) {
                        haves[i][j] = 1;
                        prob *= pers[offset + i][j];
                    } else {
                        prob *= (Mod(1) - pers[offset + i][j]);
                    }
                }
            }

            int flags = 0;
            for (int i = 0; i < 6; ++i) {
                if (!haves[0][i]) continue;
                for (int j = 0; j < 6; ++j) {
                    if (!haves[1][j]) continue;
                    if (i == j) continue;
                    for (int k = 0; k < 6; ++k) {
                        if (!haves[2][k]) continue;
                        if (i == k || j == k) continue;
                        int anum = (1 << i) ^ (1 << j) ^ (1 << k);
                        flags |= (1 << permMap[anum]);
                    }
                }
            }
            result[flags] += prob;
        }
        return result;
    };

    auto upper = solve(0);
    auto lower = solve(3);

    // FWT-style summation for lower
    for (int bit = 1; bit < (1 << 20); bit <<= 1) {
        for (int i = 0; i < (1 << 20); ++i) {
            if (!(i & bit)) {
                lower[i ^ bit] += lower[i];
            }
        }
    }

    Mod answer(0);
    for (int mask = 0; mask < (1 << 20); ++mask) {
        if (upper[mask].num == 0) continue;

        int need = 0;
        for (int x = 0; x < 20; ++x) {
            if (mask & (1 << x)) {
                need |= (1 << (19 - x));
            }
        }

        int complement = ((1 << 20) - 1) ^ need;
        Mod term = upper[mask] * (Mod(1) - lower[complement]);
        answer += term;
    }

    cout << answer.num << '\n';
    return 0;
}
